update public.lessons l set enhancements = $ench${"industryStory":"I once interviewed two candidates with near-identical Postman collections. One could explain why they'd tested those endpoints and skipped others; the other just \"tested everything they saw\". We hired the first. Scope and judgement are the whole game — the requests are the easy part.","visualAid":{"type":"comparison","title":"Good vs weak portfolio API","headers":["Trait","Good choice","Weak choice"],"rows":[["Access","Free, no card","Needs paid key"],["Lifecycle","Full CRUD","Read-only"],["Auth","Real token flow","None"],["Reliability","Stable, public","Flaky / private"],["Re-runnable","Any time","Rate-limited hard"]]},"davidTip":"I always write the scope in the same repo as the collection, as a README. When a hiring manager opens the folder, the very first thing they read is evidence that I think before I test.","miniChallenge":"In two sentences, justify your API choice: why it's a good demonstration piece and what its CRUD/auth story lets you show.","modelAnswer":"## Example\nI chose restful-booker because it has a genuine token-auth step and a full create-read-update-delete lifecycle. That lets me demonstrate happy paths, an auth negative case, and data cleanup in one coherent suite.","badGood":{"label":"project scope","bad":"\"I'll test the API.\" No endpoints listed, no objectives, no out-of-scope — impossible to judge or finish.","good":"A one-page README naming five in-scope endpoints, four objectives (CRUD, auth negative, schema), and explicitly out-of-scope performance testing."},"portfolioBuilder":"Create a project folder `api-testing-portfolio` with a `README.md` containing your scope and objectives. This folder is your capstone artefact — every later session adds to it."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 10 and l.lesson_number = 1;

update public.lessons l set enhancements = $ench${"industryStory":"A team handed me a collection that only worked on the author's machine — every URL was hard-coded to `localhost:3000`. It was useless the moment he left. We spent a day parameterising it. Build it portable from the first request and you never pay that tax.","visualAid":{"type":"timeline","title":"Data flowing through a chained suite","steps":[{"label":"Auth","detail":"POST /auth → save {{token}}"},{"label":"Create","detail":"POST /booking → save {{bookingId}}"},{"label":"Read","detail":"GET /booking/{{bookingId}}"},{"label":"Update","detail":"PUT /booking/{{bookingId}}"},{"label":"Delete","detail":"DELETE /booking/{{bookingId}} → 200/204"}]},"davidTip":"I name the collection with my own name — \"API Portfolio — David Oxley\" — and write a one-paragraph description at the top. When it's exported and shared, it always carries its own context. Never ship a collection called \"New Collection\".","badGood":{"label":"request values","bad":"`GET https://restful-booker.herokuapp.com/booking/17` with the token pasted into the header, per request.","good":"`GET {{baseUrl}}/booking/{{bookingId}}` with `Authorization: Bearer {{token}}` — driven by the active environment."},"miniChallenge":"Add a second environment to your collection and prove the whole suite runs against it by switching only the environment dropdown.","modelAnswer":"## Example\nEnvironment \"Public\" sets `baseUrl = https://restful-booker.herokuapp.com`; environment \"Local\" sets `baseUrl = http://localhost:3001`. Switching the dropdown re-points all 6 requests with zero edits.","portfolioBuilder":"Export your collection (`collection.json`) and both environments into the project folder. Commit them alongside the README so the whole suite is version-controlled and shareable."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 10 and l.lesson_number = 2;

update public.lessons l set enhancements = $ench${"industryStory":"A candidate's collection had 40 requests and every single test was `status === 200`. It looked impressive until I asked \"what happens without a token?\" — the suite had no answer. One thoughtful negative test would have told me more than all 40 green ticks.","visualAid":{"type":"comparison","title":"Weak vs strong assertions","headers":["Layer","Weak suite","Strong suite"],"rows":[["Status","Checks 200","Checks exact expected code"],["Body","Ignored","Key fields + values"],["Schema","None","jsonSchema validated"],["Negatives","None","Auth 403, not-found 404, bad-input 400"],["Cleanup","Leaves data","Deletes what it created"]]},"davidTip":"I write the negative tests first when I can. It forces me to ask \"how is this meant to fail?\" — and the answer usually reveals whether the developers thought about it at all.","badGood":{"label":"a delete test","bad":"`DELETE /booking/{{bookingId}}` asserts `200` and stops — the record might still exist.","good":"`DELETE` asserts `201`/`200`, then a follow-up `GET /booking/{{bookingId}}` asserts `404`, proving the delete actually worked."},"miniChallenge":"Add one negative test that proves authorisation is enforced, and explain in a comment what a *failure* of that test would mean for security.","modelAnswer":"## Example\n`pm.test('delete without token is rejected', () => pm.response.to.have.status(403));` — if this ever returned 200, any unauthenticated caller could delete bookings, a serious access-control flaw.","portfolioBuilder":"Store your JSON schemas in a `schemas/` folder and re-export the collection with all assertions included. Your suite is now genuinely automated — it decides pass/fail on its own."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 10 and l.lesson_number = 3;

update public.lessons l set enhancements = $ench${"industryStory":"A tester swore his suite worked — but it only ran in his Postman with his saved variables. On a clean machine it fell over instantly. The day he got it running through Newman with an exported environment, it became something the whole team could trust and put in the pipeline. Headless is the honesty test.","visualAid":{"type":"timeline","title":"From collection to shareable report","steps":[{"label":"Export","detail":"collection.json + environment.json"},{"label":"Install","detail":"npm i -g newman newman-reporter-htmlextra"},{"label":"Run","detail":"newman run … -r htmlextra"},{"label":"Report","detail":"report.html generated"},{"label":"Document","detail":"README with commands + screenshot"}]},"davidTip":"I always paste the exact command into the README, tested by copy-pasting it into a fresh terminal myself. If it doesn't run first time for me, it won't run for a hiring manager — and they won't email to ask why.","badGood":{"label":"run instructions","bad":"README says \"run the collection in Postman\". No commands, no environment, no reporter — impossible to reproduce headlessly.","good":"README lists prerequisites and one copy-pasteable `newman run …` command that produces `report.html` on a clean machine."},"miniChallenge":"On a fresh terminal, follow only your own README instructions to run the suite. Note anything that didn't work first time and fix the docs.","modelAnswer":"## Example\nMy README's \"Run\" section: `npm i -g newman newman-reporter-htmlextra` then `newman run collection.json -e public.postman_environment.json -r cli,htmlextra --reporter-htmlextra-export report.html`. Following it cold produced a green report with zero edits.","portfolioBuilder":"Commit `report.html` and a screenshot of it to the project folder, and add the run instructions to your README. Your suite is now reproducible by anyone — the hallmark of a professional artefact."}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 10 and l.lesson_number = 4;

update public.lessons l set enhancements = $ench${"industryStory":"The best junior hire I ever made linked one repo on her CV: a small but immaculate API test suite with a README I could run in a minute. It told me more than three years of \"responsible for testing\" bullet points ever could. She had proof. In the interview we just talked through her repo — she'd already passed.","visualAid":{"type":"comparison","title":"How a manager reads your portfolio","headers":["They look for","Weak signal","Strong signal"],"rows":[["Runs?","GUI-only, no instructions","One Newman command, green report"],["Judgement","Only happy paths","Negatives + auth + schema"],["Structure","Flat, unnamed","Folders, clear names, README"],["Clarity","\"How\" but no \"why\"","Value stated up front"],["Safety","Secrets committed","Placeholders, clean .gitignore"]]},"davidTip":"When I review a candidate's repo, I clone it and run it before I read a word of the CV. If it runs green in one command, I'm already leaning yes. Make that first command work, and the rest of the interview is yours to lose.","badGood":{"label":"README opening line","bad":"\"This project uses Postman and Newman and has some tests in it.\"","good":"\"An automated API test suite for restful-booker demonstrating CRUD, auth, negative and schema testing, runnable in one command with an HTML report.\""},"miniChallenge":"Rewrite your README's first two sentences so a non-technical recruiter understands what the project is and why it's impressive — no jargon.","modelAnswer":"## Example\n\"This is an automated test suite for a hotel-booking API. It proves the API works correctly, blocks unauthorised deletes, and returns the right data shape — and it runs and reports itself with a single command.\"","managersReview":{"intro":"Here's how I, as a hiring manager, would assess your finished portfolio in the two minutes I actually spend on it:","strengths":["It runs on a clean machine with one documented command","It covers full CRUD plus negative and authorisation cases","The README states the value before the mechanics","The HTML report shows every assertion, readable without Postman"],"improvements":["Add a short \"what I would test next\" section to show forward thinking","Include one data-driven run over a CSV to show scale","Wire the Newman run into a GitHub Actions badge for live CI proof"],"gaps":["No note on how the suite would slot into a real pipeline or release gate","No mention of limitations (e.g. performance/load explicitly out of scope)","No brief reflection on a bug the tests would have caught in production"]},"portfolioBuilder":"This is the finish line: your public repository IS your portfolio artefact. Confirm it runs green from a fresh clone, the README sells it in one paragraph, no secrets are committed, and the link sits on your CV. You now have proof, not claims — the outcome of the entire course.","resourcePreview":{"name":"API Portfolio Publishing Checklist","purpose":"A final checklist covering repo structure, README, secrets and CV placement.","whenToUse":"Run through it just before you make the repository public and share the link.","formats":["PDF","Markdown"]}}$ench$::jsonb
from public.modules m join public.courses c on c.id = m.course_id
where l.module_id = m.id and c.slug = 'api-testing-masterclass'
  and m.module_number = 10 and l.lesson_number = 5;

